CREATE TABLE users (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, account VARCHAR(50) NOT NULL, password_hash VARCHAR(100) NOT NULL, nickname VARCHAR(50) NOT NULL, phone VARCHAR(20) NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY(id), UNIQUE KEY uk_users_account(account), CHECK(status IN ('ACTIVE','DISABLED')));
CREATE TABLE merchants (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, account VARCHAR(50) NOT NULL, password_hash VARCHAR(100) NOT NULL, name VARCHAR(100) NOT NULL, phone VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY(id), UNIQUE KEY uk_merchants_account(account), CHECK(status IN ('ACTIVE','SUSPENDED')));
CREATE TABLE user_addresses (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, recipient VARCHAR(50) NOT NULL, phone VARCHAR(20) NOT NULL, region VARCHAR(100) NOT NULL, detail VARCHAR(200) NOT NULL, is_default BOOLEAN NOT NULL DEFAULT FALSE, deleted_at DATETIME(3) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY(id), INDEX idx_addresses_user(user_id,deleted_at));
